DROP TABLE IF EXISTS `scheme_match_snapshot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scheme_match_snapshot` (
  `snapshot_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `scheme_id` int NOT NULL,
  `confidence` enum('STRONG','PARTIAL') COLLATE utf8mb4_unicode_ci NOT NULL,
  `computed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`snapshot_id`),
  UNIQUE KEY `uq_snapshot` (`user_id`,`scheme_id`),
  KEY `fk_snapshot_scheme` (`scheme_id`),
  CONSTRAINT `fk_snapshot_scheme` FOREIGN KEY (`scheme_id`) REFERENCES `schemes` (`scheme_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_snapshot_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9346 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
