INSERT INTO `scheme_reviews` VALUES (1,1,81,5,'Direct DBT installment credited on schedule','The Aadhaar eKYC via OTP was fast and smooth. Received the payment directly into my SBI DBT-linked account in 2 weeks without visiting any government office.',5,2,1,'2026-01-01 03:40:00','2026-09-17 10:44:58'),(2,1,84,5,'Great financial relief for seasonal crop inputs','Applied online through the portal. Verified our 7/12 land extract with Talathi. Approval turnaround was roughly 3 weeks. Very transparent process.',5,3,1,'2026-02-03 04:43:00','2026-09-17 10:44:58'),(3,1,87,5,'Beneficiary status update on portal is clear','The SMS alert notifications on registration and sanction were accurate. Highly recommended for small and marginal landholding farmers.',5,4,1,'2026-03-05 05:46:00','2026-09-17 10:44:58'),(4,1,90,4,'Ensure Aadhaar name spelling matches land records','Process took 1 weeks because of initial mismatch between land record spelling and Aadhaar. Once corrected at CSC center, disbursement was credited promptly.',4,1,1,'2026-04-07 06:49:00','2026-09-17 10:44:58'),(5,1,93,3,'Seed subsidy and equipment assistance disbursed','Applied for farm machinery subsidy under this scheme. Verification committee visited within 14 days and sanctioned 50% subsidy directly.',3,2,1,'2026-05-09 07:52:00','2026-09-17 10:44:58'),(6,1,76,5,'Smooth online portal verification','Uploading the patta passbook and bank passbook was simple. Received sanction confirmation on mobile within 3 weeks.',5,3,1,'2026-06-11 08:55:00','2026-09-17 10:44:58'),(7,1,79,4,'Direct DBT installment credited on schedule','The Aadhaar eKYC via OTP was fast and smooth. Received the payment directly into my SBI DBT-linked account in 4 weeks without visiting any government office.',4,4,1,'2026-07-13 09:58:00','2026-09-17 10:44:58'),(8,1,82,5,'Great financial relief for seasonal crop inputs','Applied online through the portal. Verified our 7/12 land extract with Talathi. Approval turnaround was roughly 1 weeks. Very t