--
-- Table structure for table `schemes`
--

DROP TABLE IF EXISTS `schemes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `schemes` (
  `scheme_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `ministry` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `state` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `benefit_summary` text COLLATE utf8mb4_unicode_ci,
  `benefit_amount` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `application_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `official_portal` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `deadline` date DEFAULT NULL,
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verified_at` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`scheme_id`),
  KEY `fk_scheme_category` (`category_id`),
  KEY `idx_schemes_active` (`is_active`),
  CONSTRAINT `fk_scheme_category` FOREIGN KEY (`category_id`) REFERENCES `scheme_categories` (`category_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `schemes`
--

LOCK TABLES `schemes` WRITE;
/*!40000 ALTER TABLE `schemes` DISABLE KEYS */;
INSERT INTO `schemes` VALUES (1,'Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)','Income support to landholding farmer families','Ministry of Agriculture and Farmers Welfare',5,NULL,'Income support to landholding farmer families','₹6,000 per year in three equal installments of ₹2,000','https://pmkisan.gov.in/','https://pmkisan.gov.in/',1,'2026-09-29','https://pmkisan.gov.in/','2026-09-14','2026-09-14 17:40:02','2026-09-16 21:26:09'),(2,'Ayushman Bharat Pradhan Mantri Jan Arogya Yojana (PM-JAY)','Cashless health insurance cover for poor and vulnerable families for secondary and tertiary care','Ministry of Health and Family Welfare / National Health Authority',2,NULL,'Cashless health insurance cover for poor and vulnerable families for secondary and tertiary care','Up to ₹5,00,000 per family per year (cashless)','https://mera.pmjay.gov.in/','https://nha.gov.in/PM-JAY',1,NULL,'https://www.nha.gov.in/PM-JAY','2026-09-14','2026-09-14 17:40:02','2026-09-14 17:40:02'),(3,'Pradhan Mantri Awas Yojana - Urban (PMAY-U 2.0)','Central assistance for pucca house construction/purchase for urban poor and middle-income households','Ministry of Housing and Urban Affairs',3,NULL,'Central assistance for pucca house construction/purchase for urban poor and middle-income households','Interest subsidy / central assistance; EWS houses up to 30 sq.mt. carpet area','https://pmay-urban.gov.in/','https://pmay-urban.gov.in/',1,NULL,'https://pmay-urban.gov.in/','2026-09-14','2026-09-14 17:40:02','2026-09-14 17:40:02'),(4,'Post-Matric Scholarship for SC Students','Financial assistance (maintenance allowance + fee reimbursement) for SC students studying Class 11 and above','Ministry of Social Justice and Empowerment',1,NULL,'Financial assistance (maintenance allowance + fee reimbursement) for SC students studying Class 11 and above','Maintenance allowance and course fee reimbursement (amount varies by course/state)','https://scholarships.gov.in/','https://scholarships.gov.in/',1,NULL,'https://scholarships.gov.in/public/schemeGuidelines/DEPDFAQ.pdf','2026-09-14','2026-09-14 17:40:02','2026-09-14 17:40:02'),(5,'Pre-Matric Scholarship for Minorities','Financial assistance for minority community students studying in Classes 1 to 10','Ministry of Minority Affairs',1,NULL,'Financial assistance for minority community students studying in Classes 1 to 10','Scholarship amount varies (day scholar/hosteller rates)','https://scholarships.gov.in/','https://scholarships.gov.in/',1,NULL,'https://www.buddy4study.com/article/pre-matric-scholarship-for-minorities','2026-09-14','2026-09-14 17:40:02','2026-09-14 17:40:02'),(6,'Prime Minister\'s Employment Generation Programme (PMEGP)','Credit-linked subsidy for setting up new micro-enterprises to generate self-employment','Ministry of Micro, Small and Medium Enterprises',6,NULL,'Credit-linked subsidy for setting up new micro-enterprises to generate self-employment','Subsidy of 15%-35% of project cost (up to ₹50 lakh manufacturing / ₹20 lakh service)','https://www.kviconline.gov.in/pmegpeportal/pmegphome/index.jsp','https://www.kviconline.gov.in/pmegpeportal/pmegphome/index.jsp',1,'2026-09-28','https://www.cashfree.com/blog/pmegp-scheme-subsidy-rates-eligibility-how-to-apply/','2026-09-14','2026-09-14 17:40:02','2026-09-16 21:26:09'),(7,'Sukanya Samriddhi Yojana','Small savings scheme for the welfare of a girl child, opened by parent/guardian','Ministry of Finance / Department of Posts',4,NULL,'Small savings scheme for the welfare of a girl child, opened by parent/guardian','8.2% interest (Q2 FY2026-27); deposits ₹250 to ₹1.5 lakh/year; matures 21 years from opening','https://www.nsiindia.gov.in/','https://www.nsiindia.gov.in/',1,NULL,'https://cleartax.in/s/sukanya-samriddhi-yojana','2026-09-14','2026-09-14 17:40:02','2026-09-14 17:40:02'),(8,'Atal Pension Yojana','Guaranteed minimum pension scheme for unorganised sector workers','Ministry of Finance / PFRDA',4,NULL,'Guaranteed minimum pension scheme for unorganised sector workers