CREATE DEFINER=`root`@`localhost` FUNCTION `fn_calculate_age`(p_dob DATE) RETURNS int
    NO SQL
BEGIN
    IF p_dob IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN TIMESTAMPDIFF(YEAR, p_dob, CURDATE());
END ;;
DELIMITER ;
