CREATE DEFINER=`root`@`localhost` FUNCTION `fn_days_until_deadline`(p_deadline DATE) RETURNS int
    NO SQL
BEGIN
    IF p_deadline IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN DATEDIFF(p_deadline, CURDATE());
END ;;
